import type {ButtonHTMLAttributes,ReactNode} from 'react';import {X,LoaderCircle} from 'lucide-react';import {useToast} from '../../store/toast';
export function Button({className='',variant='primary',loading,children,...p}:ButtonHTMLAttributes<HTMLButtonElement>&{variant?:'primary'|'secondary'|'danger'|'ghost';loading?:boolean}){const styles={primary:'bg-brand-600 text-white hover:bg-brand-700',secondary:'bg-slate-900 text-white hover:bg-slate-800',danger:'bg-rose-600 text-white hover:bg-rose-700',ghost:'bg-white text-slate-700 border border-slate-200 hover:bg-slate-50'};return <button className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} disabled={loading||p.disabled} {...p}>{loading&&<LoaderCircle size={16} className="animate-spin"/>}{children}</button>}
export function Card({children,className=''}:{children:ReactNode;className?:string}){return <div className={`rounded-2xl border border-slate-200/70 bg-white shadow-soft ${className}`}>{children}</div>}
export function Badge({children,tone}:{children:ReactNode;tone?:string}){const key=(tone||String(children)).toLowerCase();const c=key.includes('complete')||key.includes('ready')||key.includes('available')||key.includes('paid')?'bg-emerald-100 text-emerald-700':key.includes('cancel')||key.includes('refund')||key.includes('low')?'bg-rose-100 text-rose-700':key.includes('prepar')||key.includes('occup')||key.includes('partial')?'bg-amber-100 text-amber-700':'bg-sky-100 text-sky-700';return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold capitalize ${c}`}>{String(children).replaceAll('-',' ')}</span>}
export function Modal({open,onClose,title,children,className='max-w-lg'}:{open:boolean;onClose:()=>void;title:string;children:ReactNode;className?:string}){if(!open)return null;return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45 p-4 backdrop-blur-sm" onMouseDown={onClose}><div className={`max-h-[90vh] w-full overflow-auto rounded-2xl bg-white shadow-2xl ${className}`} onMouseDown={e=>e.stopPropagation()}><div className="sticky top-0 z-10 flex items-center justify-between border-b bg-white px-5 py-4"><h2 className="text-lg font-bold">{title}</h2><button onClick={onClose} className="rounded-lg p-2 hover:bg-slate-100"><X size={20}/></button></div>{children}</div></div>}
export function Empty({title='Nothing here yet',text='New records will appear here.'}:{title?:string;text?:string}){return <div className="grid min-h-52 place-items-center text-center"><div><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-slate-100 text-xl">◇</div><h3 className="font-semibold">{title}</h3><p className="mt-1 text-sm text-slate-500">{text}</p></div></div>}
export function Toasts(){const {toasts,remove}=useToast();return <div className="fixed right-5 top-5 z-[100] space-y-2">{toasts.map(t=><button onClick={()=>remove(t.id)} key={t.id} className={`block min-w-64 rounded-xl px-4 py-3 text-left text-sm font-medium text-white shadow-xl ${t.kind==='error'?'bg-rose-600':t.kind==='info'?'bg-slate-800':'bg-emerald-600'}`}>{t.message}</button>)}</div>}
export function Field({label,...p}:any){return <label className="block text-sm font-medium text-slate-700">{label}<input {...p} className={`mt-1.5 w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100 ${p.className||''}`}/></label>}
